#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

ENV_FILE="${ENV_FILE:-.env.local}"
TOTAL_STAGES=5

banner "AegisSRE Live External Sources Setup"

# ── Stage 1: Google Cloud Project, Region, GKE Cluster & Gemini on Agent Platform ─
stage "Google Cloud Project, GKE Cluster & Gemini on Agent Platform"
say "Configure your Google Cloud project, region, GKE cluster, and ADK Go v2 Gemini Enterprise Agent Platform reasoning."
step "Ensure Application Default Credentials (gcloud auth application-default login) are active."
ask GOOGLE_CLOUD_PROJECT "Google Cloud Project ID (e.g. from gcloud config get-value project):"
ask GOOGLE_CLOUD_LOCATION "Google Cloud Region (default: us-central1):"
[[ -z "${GOOGLE_CLOUD_LOCATION:-}" ]] && GOOGLE_CLOUD_LOCATION="us-central1"
ask GKE_CLUSTER_NAME "GKE Cluster Name (matches your active kubectl config current-context):"
write_env GOOGLE_CLOUD_PROJECT "$GOOGLE_CLOUD_PROJECT"
write_env GOOGLE_CLOUD_LOCATION "$GOOGLE_CLOUD_LOCATION"
write_env GKE_CLUSTER_NAME "$GKE_CLUSTER_NAME"
write_env AGENT_PLATFORM_LIVE_LLM "true"

# ── Stage 2: Google Cloud Model Armor & Cloud SDP Endpoint ────────────────
stage "Google Cloud Model Armor & Cloud SDP (DLP)"
say "Configure live Model Armor prompt screening and Cloud SDP in-flight de-identification."
open_url "https://console.cloud.google.com/security/model-armor"
note "Tip: run 'gcloud model-armor templates create aegis-prompt-screen --location=${GOOGLE_CLOUD_LOCATION}' or 'make seed-live' to provision the template automatically."
step "Copy your Model Armor template sanitizeUserPrompt endpoint URL (or press Enter to auto-derive from GOOGLE_CLOUD_PROJECT)."
ask MODEL_ARMOR_ENDPOINT "Model Armor Endpoint URL (optional):"
if [[ -z "${MODEL_ARMOR_ENDPOINT:-}" && -n "${GOOGLE_CLOUD_PROJECT:-}" ]]; then
  MODEL_ARMOR_ENDPOINT="https://modelarmor.${GOOGLE_CLOUD_LOCATION}.rep.googleapis.com/v1/projects/${GOOGLE_CLOUD_PROJECT}/locations/${GOOGLE_CLOUD_LOCATION}/templates/aegis-prompt-screen:sanitizeUserPrompt"
fi
step "Copy your Cloud SDP projects.content.deidentify endpoint URL (or press Enter to auto-derive from GOOGLE_CLOUD_PROJECT)."
ask DLP_ENDPOINT "Cloud SDP / DLP Endpoint URL (optional):"
if [[ -z "${DLP_ENDPOINT:-}" && -n "${GOOGLE_CLOUD_PROJECT:-}" ]]; then
  DLP_ENDPOINT="https://dlp.googleapis.com/v2/projects/${GOOGLE_CLOUD_PROJECT}/locations/global/content:deidentify"
fi
[[ -n "${MODEL_ARMOR_ENDPOINT:-}" ]] && write_env MODEL_ARMOR_ENDPOINT "$MODEL_ARMOR_ENDPOINT"
[[ -n "${DLP_ENDPOINT:-}" ]] && write_env DLP_ENDPOINT "$DLP_ENDPOINT"

# ── Stage 3: GitHub Companion Target Repository & Persona Tokens ──────────
stage "GitHub Companion Target Repository & Persona Tokens"
say "Configure the companion target repository (gke-demos/aegis-checkout-target) and Alice/Bob 3LO tokens."
open_url "https://github.com/settings/tokens"
step "Confirm or enter the target repository slug for live advisories and Step-Up Pull Requests."
ask GITHUB_TARGET_REPO "Target GitHub Repository (default: gke-demos/aegis-checkout-target):"
[[ -z "${GITHUB_TARGET_REPO:-}" ]] && GITHUB_TARGET_REPO="gke-demos/aegis-checkout-target"
step "Paste SecOps Lead Alice's GitHub token (or leave blank to auto-detect via gh auth token)."
ask_secret ALICE_GITHUB_TOKEN "Alice GitHub Token (repo, security_events):"
step "Paste External Contractor Bob's restricted GitHub token (optional)."
ask_secret BOB_GITHUB_TOKEN "Bob GitHub Token (public_repo only, optional):"
write_env GITHUB_TARGET_REPO "$GITHUB_TARGET_REPO"
write_env LIVE_GITHUB "true"
[[ -n "${ALICE_GITHUB_TOKEN:-}" ]] && write_env ALICE_GITHUB_TOKEN "$ALICE_GITHUB_TOKEN"
[[ -n "${BOB_GITHUB_TOKEN:-}" ]] && write_env BOB_GITHUB_TOKEN "$BOB_GITHUB_TOKEN"

# ── Stage 4: Optional Gmail & Jira Cloud 3LO Credentials ──────────────────
stage "Optional Gmail & Atlassian Jira Cloud 3LO Credentials"
say "Configure optional live Jira Cloud (SEC-101 vs PUB-202) and Gmail escalation credentials."
note "Leave any field blank to use AegisSRE's deterministic per-persona fixture fallback."
ask JIRA_BASE_URL "Jira Cloud Base URL (e.g. https://your-org.atlassian.net, optional):"
ask_secret ALICE_JIRA_TOKEN "Alice Jira Cloud 3LO/API Token (access to SEC-101, optional):"
ask_secret BOB_JIRA_TOKEN "Bob Jira Cloud 3LO/API Token (PUB-202 only, 403 on SEC-101, optional):"
ask_secret ALICE_GMAIL_TOKEN "Alice Gmail OAuth Access Token (gmail.readonly, optional):"
[[ -n "${JIRA_BASE_URL:-}" ]] && write_env JIRA_BASE_URL "$JIRA_BASE_URL"
[[ -n "${ALICE_JIRA_TOKEN:-}" ]] && write_env ALICE_JIRA_TOKEN "$ALICE_JIRA_TOKEN"
[[ -n "${BOB_JIRA_TOKEN:-}" ]] && write_env BOB_JIRA_TOKEN "$BOB_JIRA_TOKEN"
[[ -n "${ALICE_GMAIL_TOKEN:-}" ]] && write_env ALICE_GMAIL_TOKEN "$ALICE_GMAIL_TOKEN"

# ── Stage 5: Agent Substrate v0.5.0 gVisor Pool Verification ──────────────
stage "Agent Substrate v0.5.0 gVisor Pool Verification"
say "Enable live Agent Substrate v0.5.0 gVisor WorkerPool & atenet Egress MITM verification."
step "Verify that manifests/01-agent-substrate-v050.yaml is applied to your active kubectl context."
ask SUBSTRATE_GATEWAY_URL "Optional Substrate Gateway URL (leave blank to auto-bridge via kubectl):"
write_env LIVE_SUBSTRATE "true"
[[ -n "${SUBSTRATE_GATEWAY_URL:-}" ]] && write_env SUBSTRATE_GATEWAY_URL "$SUBSTRATE_GATEWAY_URL"

finish
}

run_wizard "$@"; exit
